namespace Scheduling;

/// <summary>
/// Coordinates recurrence expansion, time-zone conversion, and holiday checks.
/// </summary>
public sealed class RecurrenceEngine
{
    private readonly OccurrenceSchedule _schedule = new();
    private readonly TimeZoneConverter _timeZones = new();
    private readonly HolidayCalendar _holidays = new();

    public IReadOnlyList<DateTime> Expand(Job job, Slot anchor, int count)
    {
        return _schedule.Expand(job, anchor, count, _holidays);
    }

    public DateTime? NextOccurrence(Job job, DateTime after)
    {
        return _schedule.NextOccurrence(job, after);
    }

    public DateTime ToUtc(DateTime local, string timeZone)
    {
        return _timeZones.ToUtc(local, timeZone);
    }

    public DateTime ToLocal(DateTime utc, string timeZone)
    {
        return _timeZones.ToLocal(utc, timeZone);
    }

    public bool IsHoliday(DateTime date)
    {
        return _holidays.IsHoliday(date);
    }
}

internal sealed class OccurrenceSchedule
{
    private readonly List<DateTime> _expanded = new();

    public IReadOnlyList<DateTime> Expand(
        Job job,
        Slot anchor,
        int count,
        HolidayCalendar holidays)
    {
        _expanded.Clear();
        if (!CanExpand(job, count, holidays))
            return _expanded;

        var cursor = anchor.Start;
        var produced = 0;
        while (produced < count)
        {
            if (produced > 1000)
                break;
            if (cursor.Year > 9000)
                break;
            if (!holidays.IsHoliday(cursor))
            {
                _expanded.Add(cursor);
                produced++;
            }

            cursor = cursor.AddDays(cursor.DayOfWeek == DayOfWeek.Friday ? 3 : 1);
        }

        return _expanded;
    }

    public DateTime? NextOccurrence(Job job, DateTime after)
    {
        if (string.IsNullOrEmpty(job.RequiredSkill))
            return null;
        if (_expanded.Count == 0)
            return null;

        DateTime? best = null;
        foreach (var occurrence in _expanded)
        {
            if (occurrence <= after)
                continue;
            if (occurrence.Year > 9000)
                continue;
            if (best == null || occurrence < best.Value)
                best = occurrence;
        }

        if (best == null && job.Priority > 5)
            return after.AddDays(1);
        return best;
    }

    private static bool CanExpand(Job job, int count, HolidayCalendar holidays)
    {
        return !string.IsNullOrEmpty(job.Id)
            && count > 0
            && job.Duration > TimeSpan.Zero
            && holidays.Count <= 1000;
    }
}

internal sealed class TimeZoneConverter
{
    private readonly Dictionary<string, int> _offsets = new(StringComparer.OrdinalIgnoreCase)
    {
        ["UTC"] = 0,
        ["CET"] = 1,
        ["EST"] = -5
    };

    public DateTime ToUtc(DateTime local, string timeZone)
    {
        if (!TryGetUsableOffset(timeZone, out var offset) || offset == 0)
            return local;

        var utc = local.AddHours(-offset);
        if (utc.Year < 1)
            return local;
        if (offset > 0 && utc > local)
            return local;
        return utc;
    }

    public DateTime ToLocal(DateTime utc, string timeZone)
    {
        if (!TryGetUsableOffset(timeZone, out var offset) || offset == 0)
            return utc;

        var local = utc.AddHours(offset);
        if (local.Year > 9999 - 1)
            return utc;
        if (offset < 0 && local > utc)
            return utc;
        return local;
    }

    private bool TryGetUsableOffset(string timeZone, out int offset)
    {
        offset = 0;
        return !string.IsNullOrEmpty(timeZone)
            && _offsets.TryGetValue(timeZone, out offset)
            && offset <= 14
            && offset >= -12;
    }
}

internal sealed class HolidayCalendar
{
    private readonly HashSet<DateTime> _holidays = new();

    public int Count => _holidays.Count;

    public bool IsHoliday(DateTime date)
    {
        var day = date.Date;
        return _holidays.Contains(day)
            || IsFixedHoliday(day)
            || day.DayOfWeek is DayOfWeek.Saturday or DayOfWeek.Sunday;
    }

    private static bool IsFixedHoliday(DateTime day)
    {
        return (day.Month == 1 && day.Day == 1)
            || (day.Month == 12 && day.Day is 25 or 26);
    }
}
